// Função do Spintax
function processSpintax(text) {
  let reg = /\{([^{}]+)\}/g;
  while (reg.test(text)) {
    text = text.replace(reg, (match, choices) => {
      const options = choices.split('|');
      return options[Math.floor(Math.random() * options.length)];
    });
  }
  return text;
}

// Dicionário de correções de acentuação para termos comuns
const mapaAcentos = {
  "sao": "São",
  "joao": "João",
  "conceicao": "Conceição",
  "cristovao": "Cristóvão",
  "santana": "Santana",
  "beira rio": "Beira-Rio",
  "servico": "Serviço",
  "servicos": "Serviços",
  "autenticacao": "Autenticação"
};

// NOVA FUNÇÃO: Remove subtítulos descritivos e termos jurídicos (Ex: corta " - Estética e Barbearia")
function limparNomeEmpresa(nome) {
  if (!nome) return "";

  // 1. Corta tudo que vier depois de " - ", " | " ou " – "
  let nomeLimpo = nome.split(' - ')[0];
  nomeLimpo = nomeLimpo.split(' | ')[0];
  nomeLimpo = nomeLimpo.split(' – ')[0];

  // 2. Remove termos jurídicos comuns (LTDA, ME, EPP, S/A, EIRELI)
  nomeLimpo = nomeLimpo.replace(/\s+(ltda|me|epp|s\/?a\.?|eireli)\b/gi, '');

  return nomeLimpo.trim();
}

// Função: Transforma "NOME GARRAFAL" em "Nome Garrafal" e aplica acentos comuns
function formatarNome(texto) {
  if (!texto) return "";
  return texto
    .toLowerCase()
    .split(' ')
    .map(palavra => {
      if (mapaAcentos[palavra]) {
        return mapaAcentos[palavra];
      }
      return palavra.charAt(0).toUpperCase() + palavra.slice(1);
    })
    .join(' ');
}

return $input.all().map(item => {
  const lead = item.json;

  // Limpa a sujeira do nome e depois aplica a formatação visual
  let nomeBruto = (lead.nome_negocio || "").trim();
  nomeBruto = limparNomeEmpresa(nomeBruto);
  const nomeEmpresa = formatarNome(nomeBruto);

  const bairro = formatarNome((lead.bairro || "").trim());

  // Identifica a hora atual para definir a saudação coerente
  const horaAtual = parseInt(new Date().toLocaleString("pt-BR", { timeZone: "America/Sao_Paulo", hour: "numeric" }));

  let saudacaoHorario = "bom dia";
  if (horaAtual >= 12 && horaAtual < 19) {
    saudacaoHorario = "boa tarde";
  } else if (horaAtual >= 19 || horaAtual < 5) {
    saudacaoHorario = "boa noite";
  }

  // Matriz de Templates
  const templates = [
    `{Opa|Oi|Fala} ${saudacaoHorario}! {Esse|Este} {whats|número} é da ${nomeEmpresa || "empresa"}?`,
    `${saudacaoHorario}, {td bem|blz}? {Estou|Tô} falando com a ${nomeEmpresa || "empresa"}?`,
    `{Oi|Opa}, ${saudacaoHorario}! Aqui é do {whats|contato} da ${nomeEmpresa || "empresa"}?`
  ];

  const templateSorteado = templates[Math.floor(Math.random() * templates.length)];
  let mensagem = processSpintax(templateSorteado);

  // Capitaliza o início da mensagem e qualquer letra após pontuação (. ! ?)
  mensagem = mensagem.replace(/(^|[.!?]\s+)([a-zç])/g, match => match.toUpperCase());

  return {
    json: {
      ...lead,
      mensagem_whatsapp: mensagem
    }
  };
});

// Função para ler e sortear as opções do Spintax
function processSpintax(text) {
  let matches, options, random;
  const regEx = new RegExp(/{([^{}]+?)}/);
  while ((matches = regEx.exec(text)) !== null) {
    options = matches[1].split("|");
    random = Math.floor(Math.random() * options.length);
    text = text.replace(matches[0], options[random]);
  }
  return text;
}

// Função para formatar o nome do bairro (Maiúsculas e Acentos)
function formatarBairro(nome) {
  if (!nome || nome === 'na região') return 'na região';

  // 1. Corrige acentuações comuns (tudo em minúsculo para facilitar)
  let corrigido = nome.toLowerCase()
    .replace(/\bsao\b/g, 'são')
    .replace(/\bjoao\b/g, 'joão');

  // 2. Capitaliza a primeira letra de cada palavra (ignorando de/da/do)
  return corrigido.split(' ').map(palavra => {
    if (['de', 'da', 'do', 'das', 'dos'].includes(palavra)) return palavra;
    return palavra.charAt(0).toUpperCase() + palavra.slice(1);
  }).join(' ');
}

return $input.all().map(item => {
  // 1. Puxa os dados originais do lead
  const lead = $('Buscar Lead no Supabase').first().json;

  // 2. Trata e formata o bairro com a nova função
  const bairroBruto = lead.bairro ? lead.bairro.trim() : 'na região';
  const bairro = formatarBairro(bairroBruto);

  // 3. Monta o Spintax principal
  const templateFinal = `{Vcs tão no bairro ${bairro}|Vcs ficam no bairro ${bairro}|Vi que vcs ficam no bairro ${bairro}, confere|Vcs atendem aqui no bairro ${bairro}}`;

  // 4. Roda a função Spintax para sortear o texto bruto
  let mensagem = processSpintax(templateFinal);

  // 5. Adiciona o ponto de interrogação no final SEMPRE
  mensagem += '?';

  // 6. Garante que a primeira letra da frase seja SEMPRE maiúscula
  mensagem = mensagem.charAt(0).toUpperCase() + mensagem.slice(1);

  // 7. Retorna todos os dados para o próximo nó
  item.json.mensagem_whatsapp = mensagem;
  return item;
});

// Recupera a string Base64 do nó anterior (Baixar Áudio)
let base64 = $input.item.json.base64Data || $input.item.json.base64;

if (!base64) {
  throw new Error('Base64 não encontrado na resposta da Uazapi!');
}

// Converte a string Base64 em um Buffer binário real de áudio
const buffer = Buffer.from(base64, 'base64');

// Cria a propriedade binária "data" formatada corretamente para o n8n e OpenAI
const binaryData = await this.helpers.prepareBinaryData(buffer, 'audio.ogg', 'audio/ogg');

return {
  json: $input.item.json,
  binary: {
    data: binaryData
  }
};

// Captura o output bruto do Agente
let outputRaw = $input.item.json.output;
let textoFinal = "";

try {
    let obj = typeof outputRaw === 'string' ? JSON.parse(outputRaw) : outputRaw;
    textoFinal = obj.resposta_whatsapp || "";
} catch(e) {
    textoFinal = outputRaw?.resposta_whatsapp || String(outputRaw || "");
}

// Garante que o texto seja uma string e remove quebras de linha indesejadas
textoFinal = String(textoFinal).replace(/\\n/g, " ").replace(/\n/g, " ").trim();

// TRAVA CRÍTICA: Se a IA retornar [SILENCIO] ou vazio, encerra o fluxo sem enviar nada na Uazapi
if (!textoFinal || /\[?\s*SIL[EÊ]NCIO\s*\]?/i.test(textoFinal)) {
    return [];
}

// Picota a mensagem apenas nos delimitadores "||"
let baloes = textoFinal
    .split("||")
    .map(frase => frase.trim())
    .filter(frase => frase.length > 0);

// Retorna cada pedaço limpo separadamente para o Loop
return baloes.map(frase => {
    return {
        json: {
            texto_balao: frase
        }
    };
});

