let outputRaw = $input.item.json.output;
let elogiou = false;
let descartado = false;
try {
  let obj = typeof outputRaw === 'string' ? JSON.parse(outputRaw) : outputRaw;
  elogiou = obj.elogiou === true || obj.elogiou === "true";
  descartado = obj.descartado === true || obj.descartado === "true";
} catch(e) {}
return [{ json: { elogiou: elogiou, descartado: descartado, notion_page_id: $('Buscar Lead no Supabase').first().json.notion_page_id, supabase_id: $('Buscar Lead no Supabase').first().json.id } }];

const agora = $now.setZone('America/Sao_Paulo');
const hora = agora.hour;
const diaSemana = agora.weekday;

const diaValido = diaSemana >= 1 && diaSemana <= 6;
// Ajustado para >= 7 para permitir os disparos sorteados entre 07:55 e 07:59
const horaValida = hora >= 7 && hora < 19;

// Preserva todos os dados do lead e apenas anexa a checagem no final
return $input.all().map(item => {
  item.json.pode_enviar = diaValido && horaValida;
  return item;
});

const hoje = $now.setZone('America/Sao_Paulo');
const isDomingo = hoje.weekday === 7;

// Pega o resultado do nó do Supabase
const dadosFeriado = $input.all().map(item => item.json);

// A CORREÇÃO ESTÁ AQUI: checa se tem a chave "nome" para evitar o falso-positivo do pacote vazio
const isFeriado = dadosFeriado.length > 0 && dadosFeriado[0].nome !== undefined;

const pausarHoje = isDomingo || isFeriado;

return {
  json: {
    hoje: hoje.toFormat('yyyy-MM-dd'),
    isDomingo: isDomingo,
    isFeriado: isFeriado,
    nomeFeriado: isFeriado ? `${dadosFeriado[0].nome} (${dadosFeriado[0].tipo})` : "Nenhum",
    is_dia_util: !pausarHoje
  }
};
